import nflreadpy as nflimport timeimport datetime as dt# Load current season play-by-play data#pbp = nfl.load_pbp()# Load player "game-level" stats for multiple seasons# If seasons set to True then returns ALL avaiable data# Load all available team level stats#team_stats = nfl.load_team_stats(seasons = True)#nflreadpy uses Polar => Convert to pandas#pbp_pandas = pbp.to_pandas()Options = ["week", "reg", "post", "reg+post"]def Load_Database(Entries, Seasons, Option, Filter):            player_stats = nfl.load_player_stats(Seasons, Option).to_pandas()    personal_player_stats = nfl.load_players().to_pandas()        Player_Statistics = {        "ID": player_stats["player_id"],        "ID2": personal_player_stats["gsis_id"],                "Name": player_stats["player_name"],        "Headshot": player_stats["headshot_url"],        "Birthdate": personal_player_stats["birth_date"],                "Position": player_stats["position"],        "Position Group": player_stats["position_group"],        #Touchdowns        "Passing Touchdowns": player_stats["passing_tds"],        "Rushing Touchdowns": player_stats["rushing_tds"],        "Receiving Touchdowns": player_stats["receiving_tds"],                #Yards        "Passing Yards": player_stats["passing_yards"],        "Rushing Yards": player_stats["rushing_yards"],        #Rec Yards        "Receiving Yards": player_stats["receiving_yards"],        "Receiving Yards After Catch": player_stats["receiving_yards_after_catch"],            #Attempts        #Passing        "Attempts": player_stats["attempts"],        "Completions": player_stats["completions"],        #Rushing        "Carries": player_stats["carries"],        #Receiving        "Targets": player_stats["targets"],        "Receptions": player_stats["receptions"],        "Target Share": player_stats["target_share"],                #Fumbles        "Fumbles": player_stats["def_fumbles"],                #Penalties        "Penalties": player_stats["penalties"],        "Penalty Yards": player_stats["penalty_yards"],                #Sacks Taken        "Sacks Taken": player_stats["sacks_suffered"],                #Ints Thrown        "Passing Interceptions": player_stats["passing_interceptions"],        }        Players = dict()        Total_Players = len(player_stats["player_name"])        CrossMatch = dict()        for i in range(len(personal_player_stats["gsis_id"])): #Two datasets use different IDs, this is to cross-reference players        ID2 = Player_Statistics["ID2"][i]        ID2 = str(ID2[3:])        T5 = 5 - len(ID2)        if T5 < 0:            ID2 = str(int(ID2))        ID2 = ("0" * T5) + ID2                try:            Birthdate = Player_Statistics["Birthdate"][i]        except Exception as e: # If ID is corrupted, equal to NaN, or some other case            Birthdate = str(dt.datetime.now()).split()[0]                    CrossMatch[ID2] = {"Birthdate": Birthdate}        if Entries == 0:        return    i = 0        time_start = time.time()    for i in range(Total_Players):                FilterFlag = 0        if len(Filter) > 0:            Total_Yards = Player_Statistics["Passing Yards"][i] + Player_Statistics["Rushing Yards"][i] + Player_Statistics["Receiving Yards"][i]            Total_Touchdowns = Player_Statistics["Passing Touchdowns"][i] + Player_Statistics["Rushing Touchdowns"][i] + Player_Statistics["Receiving Touchdowns"][i]                        for key, value in Filter.items():                try:                    Checked_Key_Flag = False                    Checked_Key = True                    if key == "Total Yards" or key == "Yards":                        Checked_Key = Total_Yards                    elif key == "Total Touchdowns" or key == "Touchdowns":                        Checked_Key = Total_Touchdowns                    elif key == "ID": # and 0 != i != Total_Players: #Format: 00-XXXXXXXX                        Checked_Key = int(str(Player_Statistics[key][i])[4:]) #Format: XXXXXXX (2-6 leading zeros)                    elif (key == "Position" or key == "Position Group") and type(value) == list:                        Checked_Key = Player_Statistics[key][i]                        if value.count(Checked_Key) > 0:                            Checked_Key_Flag = True                            FilterFlag += 1                        continue                    elif key == "Age":                        Age = CrossMatch[Player_Statistics["ID"][i]]#["Birthdate"]                        if Seasons[-1] != int(str(dt.datetime.now().year).split("-")[0]):                            Age = dt.date(Seasons[-1], 12, 31) - dt.date(int(Age.split("-")[0]), int(Age.split("-")[1]), int(Age.split("-")[2]))                        else:                            Age = dt.date(Seasons[-1], dt.datetime.now().month, dt.datetime.now().day) - dt.date(int(Age.split("-")[0]), int(Age.split("-")[1]), int(Age.split("-")[2]))                        Checked_Key = round(int(str(Age).split()[0]) / 365, 1)                                            else:                        Checked_Key = Player_Statistics[key][i]                    if value[0].strip() in "<>" and value[1] != "=":                        Comparison_Sign = value[0]                        if Comparison_Sign == "<":                            if int(Checked_Key) < int(value[1:]):                                Checked_Key_Flag = True                                                        elif Comparison_Sign == ">":                            if int(Checked_Key) > int(value[1:]):                                Checked_Key_Flag = True                                                elif value.strip()[:2] == "!=":                        if int(Checked_Key) != int(value[2:]):                            Checked_Key_Flag = True                                            elif value.strip()[:2] == ">=":                        if int(Checked_Key) >= int(value[2:]):                            Checked_Key_Flag = True                                            elif value.strip()[:2] == "<=":                        if int(Checked_Key) <= int(value[2:]):                            Checked_Key_Flag = True                                           else:                        if Checked_Key == value:                            Checked_Key_Flag = True                                        if Checked_Key_Flag == True:                        FilterFlag += 1                                    except Exception as e: #Filter Error: Invalid keyword                    continue            if FilterFlag != len(Filter):                continue        try:            Player_ID = int(str(Player_Statistics["ID"][i])[4:])        except:            continue        Players[Player_ID] = {}        for key, value in Player_Statistics.items():                                if key == "Name": #Special keys                Players[Player_ID].update({key: value[i]})                continue            elif key == "ID": # and 0 != i != Total_Players: #Format: 00-XXXXXXXX                try:                    Players[Player_ID].update({key: int(str(value[i])[4:])}) #Format: XXXXXXX (2-6 leading zeros)                except: # If ID is corrupted, equal to NaN, or some other case                    Players[Player_ID].update({key: -1})                continue            elif key == "Position" or key == "Position Group":                Players[Player_ID].update({key: value[i]})            elif key == "Birthdate":                try: #                   Age = value[i]                    Age = CrossMatch[str(Player_ID)]["Birthdate"]                    if Seasons[-1] != int(str(dt.datetime.now().year).split("-")[0]):                        Age = dt.date(Seasons[-1], 12, 31) - dt.date(int(Age.split("-")[0]), int(Age.split("-")[1]), int(Age.split("-")[2]))                    else:                        Age = dt.date(Seasons[-1], dt.datetime.now().month, dt.datetime.now().day) - dt.date(int(Age.split("-")[0]), int(Age.split("-")[1]), int(Age.split("-")[2]))                                        Years = round(int(str(Age).split()[0]) / 365, 1)                                        Players[Player_ID].update({"Age": Years})                except Exception as e:                    print(e)                    Players[Player_ID].update({"Age": 0})                    continue                        try:                Players[Player_ID].update({key: int(value[i])})            except: #Exception as e:                Players[Player_ID].update({key: value[i]})    #            print(f"Error: {e}")                        Total_Yards = Players[Player_ID]["Passing Yards"] + Players[Player_ID]["Rushing Yards"] + Players[Player_ID]["Receiving Yards"]        Total_Touchdowns = Players[Player_ID]["Passing Touchdowns"] + Players[Player_ID]["Rushing Touchdowns"] + Players[Player_ID]["Receiving Touchdowns"]                Players[Player_ID]["Total Yards"] = Total_Yards        Players[Player_ID]["Total Touchdowns"] = Total_Touchdowns                if len(Players) >= Entries and Entries != -1: #Capped at n entries            break        i += 1            time_end = time.time()    time_difference = time_end - time_start    Entries_Per_Second = i / time_difference    if __name__ == "__main__":        print("Took {:.6f} seconds to analyze {} entries! (With the given filter: {}, only {} entries were added.) (Rate of 1 entry per {:.4f} milliseconds, or {:.0f} entries per second)".format(time_difference, i + 1, Filter, len(Players), (1 / Entries_Per_Second) * 1000, Entries_Per_Second)) #Roughly 0.775s (Projected 0.75s) for 51k entries. O(N) time complexity (0.000015s per entry). Not bad!        return Players#Load_Database(15, [2025, 2025], Options[-1], {"Position": ["RB", "CB"]})